-- ======================================================================================================
-- MANUAL (hand-written): integrity that Prisma cannot express. Everything below is a backstop; the API
-- enforces the same rules and returns clear errors first.
-- ======================================================================================================

-- BANT: ratings are enumerated; the score is derived by the API and bounded here.
ALTER TABLE "lead_qualifications"
  ADD CONSTRAINT "lead_qualifications_score_chk" CHECK ("score" BETWEEN 0 AND 100),
  ADD CONSTRAINT "lead_qualifications_pass_mark_chk" CHECK ("pass_mark" BETWEEN 0 AND 100),
  ADD CONSTRAINT "lead_qualifications_passed_chk" CHECK ("passed" = ("score" >= "pass_mark"));
-- An override is only meaningful on a transition to QUALIFIED.
ALTER TABLE "lead_stage_history"
  ADD CONSTRAINT "lead_stage_history_override_chk" CHECK (NOT "qualification_override" OR "to_stage" = 'QUALIFIED');

-- Money and quantities are never negative; percentages are bounded; currency is KES or USD.
ALTER TABLE "catalogue_items"
  ADD CONSTRAINT "catalogue_items_money_chk" CHECK ("default_days" >= 0 AND "default_price" >= 0),
  ADD CONSTRAINT "catalogue_items_currency_chk" CHECK ("currency" IN ('KES', 'USD')),
  ADD CONSTRAINT "catalogue_items_name_chk" CHECK (NULLIF(BTRIM("name"), '') IS NOT NULL);

ALTER TABLE "tor_versions"
  ADD CONSTRAINT "tor_versions_version_no_chk" CHECK ("version_no" > 0),
  ADD CONSTRAINT "tor_versions_currency_chk" CHECK ("currency" IN ('KES', 'USD')),
  ADD CONSTRAINT "tor_versions_money_chk" CHECK (
    "setup_fee" >= 0 AND "discount_value" >= 0 AND "hosting_amount" >= 0 AND "scope_total" >= 0
    AND "addons_total" >= 0 AND "one_off_subtotal" >= 0 AND "discount_amount" >= 0 AND "net_one_off" >= 0
    AND "vat_one_off" >= 0 AND "total_one_off" >= 0 AND "recurring_vat" >= 0 AND "recurring_total" >= 0),
  ADD CONSTRAINT "tor_versions_discount_chk" CHECK (
    ("discount_type" = 'NONE' AND "discount_value" = 0)
    OR ("discount_type" = 'PERCENT' AND "discount_value" > 0 AND "discount_value" <= 100)
    OR ("discount_type" = 'AMOUNT' AND "discount_value" > 0)),
  ADD CONSTRAINT "tor_versions_vat_chk" CHECK ("vat_rate" >= 0 AND "vat_rate" <= 100),
  ADD CONSTRAINT "tor_versions_hosting_chk" CHECK ("hosting_amount" = 0 OR "hosting_cycle" IS NOT NULL),
  -- the status and its evidence travel together
  ADD CONSTRAINT "tor_versions_sent_chk" CHECK (
    ("status" = 'DRAFT' AND "sent_at" IS NULL AND "content_hash" IS NULL)
    OR ("status" <> 'DRAFT' AND "sent_at" IS NOT NULL AND "sent_by_user_id" IS NOT NULL AND "content_hash" ~ '^[0-9a-f]{64}$')),
  ADD CONSTRAINT "tor_versions_signed_chk" CHECK (("status" = 'SIGNED') = ("signed_at" IS NOT NULL)),
  ADD CONSTRAINT "tor_versions_approval_chk" CHECK (
    ("discount_approved_by_user_id" IS NULL) = ("discount_approved_at" IS NULL));

ALTER TABLE "tor_scope_items"
  ADD CONSTRAINT "tor_scope_items_name_chk" CHECK (NULLIF(BTRIM("name"), '') IS NOT NULL),
  ADD CONSTRAINT "tor_scope_items_money_chk" CHECK ("estimate_days" >= 0 AND "price" >= 0);
ALTER TABLE "tor_addons"
  ADD CONSTRAINT "tor_addons_desc_chk" CHECK (NULLIF(BTRIM("description"), '') IS NOT NULL),
  ADD CONSTRAINT "tor_addons_money_chk" CHECK ("quantity" > 0 AND "unit_price" >= 0);
ALTER TABLE "tor_milestones"
  ADD CONSTRAINT "tor_milestones_name_chk" CHECK (NULLIF(BTRIM("name"), '') IS NOT NULL);
ALTER TABLE "tor_signatures"
  ADD CONSTRAINT "tor_signatures_name_chk" CHECK (NULLIF(BTRIM("signer_name"), '') IS NOT NULL),
  ADD CONSTRAINT "tor_signatures_hash_chk" CHECK ("content_hash" ~ '^[0-9a-f]{64}$');

ALTER TABLE "quotations"
  ADD CONSTRAINT "quotations_currency_chk" CHECK ("currency" IN ('KES', 'USD')),
  ADD CONSTRAINT "quotations_money_chk" CHECK (
    "discount_value" >= 0 AND "hosting_amount" >= 0 AND "one_off_subtotal" >= 0 AND "discount_amount" >= 0
    AND "net_one_off" >= 0 AND "vat_one_off" >= 0 AND "total_one_off" >= 0 AND "recurring_vat" >= 0 AND "recurring_total" >= 0),
  ADD CONSTRAINT "quotations_kind_chk" CHECK (("kind" = 'FROM_TOR') = ("tor_version_id" IS NOT NULL)),
  ADD CONSTRAINT "quotations_decided_chk" CHECK (
    ("status" IN ('ACCEPTED', 'REJECTED')) = ("decided_at" IS NOT NULL)),
  ADD CONSTRAINT "quotations_sent_chk" CHECK ("status" = 'DRAFT' OR "sent_at" IS NOT NULL);
ALTER TABLE "quotation_lines"
  ADD CONSTRAINT "quotation_lines_money_chk" CHECK ("quantity" > 0 AND "unit_price" >= 0 AND "line_total" >= 0),
  ADD CONSTRAINT "quotation_lines_desc_chk" CHECK (NULLIF(BTRIM("description"), '') IS NOT NULL);

ALTER TABLE "client_accounts"
  ADD CONSTRAINT "client_accounts_currency_chk" CHECK ("currency" IN ('KES', 'USD')),
  ADD CONSTRAINT "client_accounts_plan_chk" CHECK ("plan_amount" >= 0);

ALTER TABLE "number_sequences" ADD CONSTRAINT "number_sequences_value_chk" CHECK ("last_value" >= 0);

-- ------------------------------------------------------------------------------------------------------
-- ToR versions: DRAFT is editable; once SENT the content is frozen. The only changes allowed afterwards are
-- the status moving forward (SENT -> SIGNED or SUPERSEDED) with signed_at set, and updated_at. SIGNED and
-- SUPERSEDED versions cannot change at all. Rows cannot be deleted (privilege revoked below, trigger here).
-- ------------------------------------------------------------------------------------------------------
CREATE FUNCTION tor_versions_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'tor versions are never deleted' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD."status" = 'DRAFT' THEN
    IF NEW."status" NOT IN ('DRAFT', 'SENT') THEN
      RAISE EXCEPTION 'a draft can only be sent' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NEW."tor_id" <> OLD."tor_id" OR NEW."version_no" <> OLD."version_no" THEN
      RAISE EXCEPTION 'a version cannot move to another ToR or number' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD."status" = 'SENT' AND NEW."status" IN ('SIGNED', 'SUPERSEDED') THEN
    -- SIGNED means both parties signed this exact version; SUPERSEDED never applies to a signed one.
    IF NEW."status" = 'SIGNED' AND (SELECT COUNT(DISTINCT "party") FROM "tor_signatures" WHERE "tor_version_id" = OLD."id") <> 2 THEN
      RAISE EXCEPTION 'a version is signed only when both parties have signed it' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF (to_jsonb(NEW) - 'status' - 'signed_at' - 'updated_at') IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'signed_at' - 'updated_at') THEN
      RAISE EXCEPTION 'a sent ToR version is frozen: only its status may change' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'a % ToR version cannot be changed', OLD."status" USING ERRCODE = 'integrity_constraint_violation';
END $$;
CREATE TRIGGER tor_versions_guard_trg BEFORE UPDATE OR DELETE ON "tor_versions"
  FOR EACH ROW EXECUTE FUNCTION tor_versions_guard();

-- Only one live (DRAFT or SENT) version per ToR: a new round cannot start while another is open.
CREATE UNIQUE INDEX "tor_versions_one_open_idx" ON "tor_versions"("tor_id") WHERE "status" IN ('DRAFT', 'SENT');
-- At most one signed version per ToR (the agreement).
CREATE UNIQUE INDEX "tor_versions_one_signed_idx" ON "tor_versions"("tor_id") WHERE "status" = 'SIGNED';

-- Children of a version (scope, add-ons, milestones) can only change while the version is a DRAFT.
CREATE FUNCTION tor_children_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_id uuid;
  v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN v_id := OLD."tor_version_id"; ELSE v_id := NEW."tor_version_id"; END IF;
  SELECT "status"::text INTO v_status FROM "tor_versions" WHERE "id" = v_id;
  IF v_status IS DISTINCT FROM 'DRAFT' THEN
    RAISE EXCEPTION 'only a draft ToR version can be changed (this one is %)', COALESCE(v_status, 'missing')
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER tor_scope_items_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "tor_scope_items"
  FOR EACH ROW EXECUTE FUNCTION tor_children_guard();
CREATE TRIGGER tor_addons_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "tor_addons"
  FOR EACH ROW EXECUTE FUNCTION tor_children_guard();
CREATE TRIGGER tor_milestones_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "tor_milestones"
  FOR EACH ROW EXECUTE FUNCTION tor_children_guard();

-- Signatures are insert-only, only on a SENT version, and must carry that version's content hash, so a
-- signature can never be attached to content other than what was sent.
CREATE FUNCTION tor_signatures_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_status text;
  v_hash text;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'signatures are insert-only' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  SELECT "status"::text, "content_hash" INTO v_status, v_hash FROM "tor_versions" WHERE "id" = NEW."tor_version_id";
  IF v_status IS DISTINCT FROM 'SENT' THEN
    RAISE EXCEPTION 'only a sent ToR version can be signed (this one is %)', COALESCE(v_status, 'missing')
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW."content_hash" IS DISTINCT FROM v_hash THEN
    RAISE EXCEPTION 'the signature does not match the sent content' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER tor_signatures_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "tor_signatures"
  FOR EACH ROW EXECUTE FUNCTION tor_signatures_guard();

-- Qualifications are an append-only history.
CREATE FUNCTION lead_qualifications_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'qualification assessments are insert-only' USING ERRCODE = 'integrity_constraint_violation';
END $$;
CREATE TRIGGER lead_qualifications_guard_trg BEFORE UPDATE OR DELETE ON "lead_qualifications"
  FOR EACH ROW EXECUTE FUNCTION lead_qualifications_guard();

-- A client account can only come from a SIGNED version that carries BOTH parties' signatures.
CREATE FUNCTION client_accounts_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_status text;
  v_tor uuid;
  v_parties int;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    IF NEW."signed_tor_version_id" <> OLD."signed_tor_version_id" OR NEW."lead_id" <> OLD."lead_id" OR NEW."tor_id" <> OLD."tor_id" THEN
      RAISE EXCEPTION 'a client account stays tied to its signed agreement' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT "status"::text, "tor_id" INTO v_status, v_tor FROM "tor_versions" WHERE "id" = NEW."signed_tor_version_id";
  IF v_status IS DISTINCT FROM 'SIGNED' OR v_tor IS DISTINCT FROM NEW."tor_id" THEN
    RAISE EXCEPTION 'a client account needs a signed ToR version' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  SELECT COUNT(DISTINCT "party") INTO v_parties FROM "tor_signatures" WHERE "tor_version_id" = NEW."signed_tor_version_id";
  IF v_parties <> 2 THEN
    RAISE EXCEPTION 'both parties must have signed the version' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER client_accounts_guard_trg BEFORE INSERT OR UPDATE ON "client_accounts"
  FOR EACH ROW EXECUTE FUNCTION client_accounts_guard();

-- Quotation content is frozen once it leaves DRAFT; only the status and decision fields move.
CREATE FUNCTION quotations_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'quotations are never deleted' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD."status" = 'DRAFT' THEN RETURN NEW; END IF;
  IF (to_jsonb(NEW) - 'status' - 'decided_at' - 'updated_at') IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'decided_at' - 'updated_at') THEN
    RAISE EXCEPTION 'a quotation that was sent cannot be edited' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER quotations_guard_trg BEFORE UPDATE OR DELETE ON "quotations"
  FOR EACH ROW EXECUTE FUNCTION quotations_guard();

CREATE FUNCTION quotation_lines_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_id uuid;
  v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN v_id := OLD."quotation_id"; ELSE v_id := NEW."quotation_id"; END IF;
  SELECT "status"::text INTO v_status FROM "quotations" WHERE "id" = v_id;
  IF v_status IS DISTINCT FROM 'DRAFT' THEN
    RAISE EXCEPTION 'only a draft quotation can change its lines' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER quotation_lines_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "quotation_lines"
  FOR EACH ROW EXECUTE FUNCTION quotation_lines_guard();

-- The runtime role cannot delete or truncate any of the business records of this workflow. Drafts replace
-- their children (scope, add-ons, milestones, quotation lines), so those keep DELETE; the triggers above
-- stop that outside a DRAFT.
REVOKE DELETE, TRUNCATE ON "lead_qualifications", "tors", "tor_versions", "tor_signatures",
  "quotations", "client_accounts", "number_sequences", "system_settings", "catalogue_items" FROM autonova_app;
REVOKE UPDATE ON "lead_qualifications", "tor_signatures" FROM autonova_app;
REVOKE TRUNCATE ON "tor_scope_items", "tor_addons", "tor_milestones", "quotation_lines" FROM autonova_app;
